import re
from typing import Any, Mapping


_PLACEHOLDER = re.compile(r"\{\{(.+?)\}\}", re.DOTALL)

_FILTERS = {"upper": "upper", "lower": "lower", "title": "title", "trim": "strip"}


def _lookup(context: Mapping[str, Any], path: str) -> Any:
    value: Any = context
    for part in path.split("."):
        if not isinstance(value, Mapping):
            raise KeyError(part)
        value = value[part]
    return value


def _render_placeholder(inside: str) -> str:
    parts = [p.strip() for p in inside.split("|")]
    name = parts[0]
    value = str(_lookup(context_global, name))
    for f in parts[1:]:
        if f not in _FILTERS:
            raise ValueError(f"unknown filter: {f!r}")
        value = getattr(value, _FILTERS[f])()
    return value


context_global: Mapping[str, Any] = {}


def render_template(template: str, context: Mapping[str, Any]) -> str:
    global context_global
    context_global = context

    def repl(match: re.Match) -> str:
        return _render_placeholder(match.group(1))

    return _PLACEHOLDER.sub(repl, template)
